import { MakeLogicType, actions, afterMount, kea, listeners, path, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'
import posthog from 'posthog-js'

import { ApiError } from 'lib/api'
import { lemonToast } from 'lib/lemon-ui/LemonToast/LemonToast'

import { listLibraries, updateLibrary } from '../../api'
import type { KnowledgeLibraryApi } from '../../generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface learnedLibrariesLogicValues {
    lastReceivingLibraryId: string | null
    libraries: KnowledgeLibraryApi[] | null
    librariesLoading: boolean
    libraryRows: LearnedLibraryRow[]
    savingLibraryIds: string[]
    sortedLibraries: KnowledgeLibraryApi[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface learnedLibrariesLogicActions {
    finishSaving: (libraryId: string) => {
        libraryId: string
    }
    librarySaved: (library: KnowledgeLibraryApi) => {
        library: KnowledgeLibraryApi
    }
    loadLibraries: () => any
    loadLibrariesFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadLibrariesSuccess: (
        libraries: KnowledgeLibraryApi[],
        payload?: any
    ) => {
        libraries: KnowledgeLibraryApi[]
        payload?: any
    }
    setReceivesLearnedSources: (
        libraryId: string,
        enabled: boolean
    ) => {
        enabled: boolean
        libraryId: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface learnedLibrariesLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        sortedLibraries: (libraries: KnowledgeLibraryApi[] | null) => KnowledgeLibraryApi[]
        libraryRows: (
            sortedLibraries: KnowledgeLibraryApi[],
            savingLibraryIds: string[],
            lastReceivingLibraryId: string | null
        ) => LearnedLibraryRow[]
        lastReceivingLibraryId: (libraries: KnowledgeLibraryApi[] | null) => string | null
    }
}

export type learnedLibrariesLogicType = MakeLogicType<
    learnedLibrariesLogicValues,
    learnedLibrariesLogicActions,
    Record<string, any>,
    learnedLibrariesLogicMeta
>

export interface LearnedLibraryRow {
    id: string
    name: string
    receivesLearnedSources: boolean
    /** Set while the row saves, and on the last receiving library, which cannot be cleared. */
    disabledReason: string | undefined
}

export const learnedLibrariesLogic = kea<learnedLibrariesLogicType>([
    path(['products', 'business_knowledge', 'frontend', 'settings', 'learnedLibrariesLogic']),
    actions({
        setReceivesLearnedSources: (libraryId: string, enabled: boolean) => ({ libraryId, enabled }),
        finishSaving: (libraryId: string) => ({ libraryId }),
        librarySaved: (library: KnowledgeLibraryApi) => ({ library }),
    }),
    loaders(() => ({
        libraries: [
            null as KnowledgeLibraryApi[] | null,
            {
                loadLibraries: async () => await listLibraries(),
            },
        ],
    })),
    reducers({
        libraries: {
            setReceivesLearnedSources: (
                state: KnowledgeLibraryApi[] | null,
                { libraryId, enabled }: { libraryId: string; enabled: boolean }
            ): KnowledgeLibraryApi[] | null =>
                state
                    ? state.map((library) => (library.id === libraryId ? { ...library, is_default: enabled } : library))
                    : state,
            // A reload that another checkbox's failure started can land before this save and show the old value.
            // The saved row from the response puts the right value back.
            librarySaved: (
                state: KnowledgeLibraryApi[] | null,
                { library }: { library: KnowledgeLibraryApi }
            ): KnowledgeLibraryApi[] | null =>
                state ? state.map((existing) => (existing.id === library.id ? library : existing)) : state,
        },
        savingLibraryIds: [
            [] as string[],
            {
                setReceivesLearnedSources: (state, { libraryId }) => [...state, libraryId],
                finishSaving: (state, { libraryId }) => state.filter((id) => id !== libraryId),
            },
        ],
    }),
    selectors({
        // The API lists receiving libraries first. Sorting by name keeps a row in place when its checkbox changes.
        sortedLibraries: [
            (s) => [s.libraries],
            (libraries: KnowledgeLibraryApi[] | null): KnowledgeLibraryApi[] =>
                [...(libraries ?? [])].sort((a, b) => a.name.localeCompare(b.name) || a.id.localeCompare(b.id)),
        ],
        libraryRows: [
            (s) => [s.sortedLibraries, s.savingLibraryIds, s.lastReceivingLibraryId],
            (
                sortedLibraries: KnowledgeLibraryApi[],
                savingLibraryIds: string[],
                lastReceivingLibraryId: string | null
            ): LearnedLibraryRow[] =>
                sortedLibraries.map((library) => ({
                    id: library.id,
                    name: library.name,
                    receivesLearnedSources: library.is_default,
                    disabledReason: savingLibraryIds.includes(library.id)
                        ? 'Saving'
                        : library.id === lastReceivingLibraryId
                          ? 'At least one library must receive learned sources'
                          : undefined,
                })),
        ],
        lastReceivingLibraryId: [
            (s) => [s.libraries],
            (libraries: KnowledgeLibraryApi[] | null): string | null => {
                const receiving = (libraries ?? []).filter((library) => library.is_default)
                return receiving.length === 1 ? receiving[0].id : null
            },
        ],
    }),
    listeners(({ actions }) => ({
        setReceivesLearnedSources: async ({ libraryId, enabled }) => {
            try {
                actions.librarySaved(await updateLibrary(libraryId, { is_default: enabled }))
            } catch (error) {
                // The reducer already shows the new value, so the reload puts the saved one back.
                actions.loadLibraries()
                lemonToast.error(
                    (error instanceof ApiError && error.detail) || 'Could not change the library. Try again.'
                )
                return
            } finally {
                actions.finishSaving(libraryId)
            }
            posthog.capture('business knowledge learned sources library toggled', { enabled })
        },
    })),
    afterMount(({ actions }) => {
        actions.loadLibraries()
    }),
])
